package com.punjab.oms.ar.mapper.finance;
import com.baomidou.mybatisplus.core.mapper.BaseMapper;import com.punjab.oms.ar.domain.entity.finance.*;import com.punjab.oms.ar.domain.bo.finance.LifecycleQueryBO;import org.apache.ibatis.annotations.*;import java.util.List;
/** 事件用EXISTS去重；变化再次限定当前单据，避免跨单事件泄露。 @author Punjab */
@Mapper public interface LifecycleMapper extends BaseMapper<ArEvent> {
 @Select("SELECT COUNT(*) FROM oms_ar_lifecycle_event e WHERE e.delete_status=false AND EXISTS(SELECT 1 FROM oms_ar_lifecycle_change c WHERE c.event_id=e.id AND c.delete_status=false AND ((c.object_type='DOCUMENT' AND c.object_id=#{documentId}) OR (c.object_type='LINE' AND EXISTS(SELECT 1 FROM oms_ar_line l WHERE l.id=c.object_id AND l.document_id=#{documentId} AND l.legal_entity_id=#{legalEntityId} AND l.delete_status=false))))") long count(LifecycleQueryBO query);
 @Select("SELECT e.* FROM oms_ar_lifecycle_event e WHERE e.delete_status=false AND EXISTS(SELECT 1 FROM oms_ar_lifecycle_change c WHERE c.event_id=e.id AND c.delete_status=false AND ((c.object_type='DOCUMENT' AND c.object_id=#{documentId}) OR (c.object_type='LINE' AND EXISTS(SELECT 1 FROM oms_ar_line l WHERE l.id=c.object_id AND l.document_id=#{documentId} AND l.legal_entity_id=#{legalEntityId} AND l.delete_status=false)))) ORDER BY e.id DESC LIMIT #{size} OFFSET #{offset}") List<ArEvent> page(LifecycleQueryBO query);
 @Select("<script>SELECT c.* FROM oms_ar_lifecycle_change c WHERE c.event_id IN <foreach collection='eventIds' item='id' open='(' separator=',' close=')'>#{id}</foreach> AND c.delete_status=false AND ((c.object_type='DOCUMENT' AND c.object_id=#{query.documentId}) OR (c.object_type='LINE' AND EXISTS(SELECT 1 FROM oms_ar_line l WHERE l.id=c.object_id AND l.document_id=#{query.documentId} AND l.legal_entity_id=#{query.legalEntityId} AND l.delete_status=false))) ORDER BY c.id</script>") List<ArChange> changes(@Param("query") LifecycleQueryBO query,@Param("eventIds") List<Long> eventIds);
}
